\label{thm:mainthem}
	For the homogeneous Ising tree with zero external field $\mathcal{T}$ parameterized by $0<\rho<1$ that satisfies Assumption \ref{assump:smalldeg}, the error exponent of the \ac{alathe} algorithm is at least $c_{\rho}$ times the 
	error exponent of the passive learning algorithm $K _{{\rm passive}}(\rho)$, i.e.,
	\begin{align}
		K _{{\rm active}}(\mathcal{T},\rho)\geq c_{\rho}K _{{\rm passive}}(\mathcal{T},\rho) \quad \forall\, \mathcal{T}\in\mathfrak{T}^{p},
	\end{align}
	where $c_{\rho}$ is the piecewise constant function   defined in Table~\ref{table:crho}.

\begin{align}
		K _{{\rm active}}(\mathcal{T},\rho)\geq c_{\rho}K _{{\rm passive}}(\mathcal{T},\rho) \quad \forall\, \mathcal{T}\in\mathfrak{T}^{p},
	\end{align}

 \label{def:thop}
	Let $i_{k_{1}}-i_{k_{2}}-\cdots -i_{k_{t+1}}$ be a   path $\mathcal{P}_{t}$ of length $t$. The corresponding $t$-hop error is defined as the event $E_{t}(\mathcal{P}_{t},m)=\bigcup_{j=1}^{t}\{\hat{\rho}_{k_{1}k_{t+1}}(m)\geq \hat{\rho}_{k_{j}k_{j+1}}(m)\}$. A graph 
	$\mathcal{G}$ has a $t$-hop error if one of its subgraphs is a path that has a $t$-hop error. This error event   is denoted as $E_{t}(\mathcal{G},m)=\cup_{\mathcal{P}_{t} \subseteq \mathcal{G}}E_{t}(\mathcal{P}_{t},m).$

For a homogeneous tree Ising with zero external field $\mathcal{T}$ parameterized by $0<\rho<1$, the exponent corresponding to the $t$-hop error event is defined as
\begin{align}\label{eq:thopee}
	K _{t}(\mathcal{T},\rho)\triangleq \varliminf_{n\rightarrow \infty}-\frac{1}{n}\log\Pr \big(E_{t}(\mathcal{T},n)\big),
\end{align}
where $n$ is the number of vector samples used for estimating correlations between nodes $\hat{\rho}_{ij}$.

\begin{align}\label{eq:thopee}
	K _{t}(\mathcal{T},\rho)\triangleq \varliminf_{n\rightarrow \infty}-\frac{1}{n}\log\Pr \big(E_{t}(\mathcal{T},n)\big),
\end{align}

For a homogeneous Ising tree with zero external field $\mathcal{T}$ parameterized by $0<\rho<1$, the exponent corresponding to the $t$-hop error event with $\alpha$ fraction of samples $E_{t}(\hat{\mathcal{T}}_{{\rm SCL}},\mathcal{T},\alpha n)$ is defined as
\begin{align}
	K_{t}(\mathcal{T},\rho,P_{\alpha})\triangleq\varliminf_{n\rightarrow\infty} -\frac{1}{n}\log\mathbb{E}_{\alpha}\big[\Pr\big(E_{t}(\hat{\mathcal{T}}_{{\rm SCL}},\mathcal{T},\alpha n)\,\big|\,\alpha \big)\big],
\end{align}
where $P_{\alpha}$ is the probability distribution of random variable $\alpha$.

\begin{align}
	K_{t}(\mathcal{T},\rho,P_{\alpha})\triangleq\varliminf_{n\rightarrow\infty} -\frac{1}{n}\log\mathbb{E}_{\alpha}\big[\Pr\big(E_{t}(\hat{\mathcal{T}}_{{\rm SCL}},\mathcal{T},\alpha n)\,\big|\,\alpha \big)\big],
\end{align}

On the event $\{\alpha=\alpha_{0}\}$ (i.e., $P_\alpha$ is the Dirac measure at $\alpha_0$) where $\alpha_{0}\in(0,1]$, we have
