	\end{align}

Let $\mathcal{G}$ be a graph and $\{e,e^{\prime}\}$ be two pairs of nodes that do not necessarily  belong to $\mathcal{G}$. The {\em edge geodesic pre-distance} is given by
\begin{align}
	d_{\mathcal{G}}(e,e^{\prime})\triangleq \min_{u\in e,v\in e^{\prime}} |{\rm Path}_{\mathcal{G}}(u,v)|.
\end{align}
If there is no path between  every $u\in e$ and $v\in e^{\prime}$, $d_{\mathcal{G}}(e,e^{\prime})=\infty$.

\begin{align}
		d_{\mathcal{G}}(e,e^{\prime})\triangleq \min_{u\in e,v\in e^{\prime}} |{\rm Path}_{\mathcal{G}}(u,v)|.
	\end{align}

Given a graph $\mathcal{G}=(\mathcal{V},\mathcal{E})$ and a collection of edges $\mathcal{C}$ with vertices in $\mathcal{V}$, an $r$-packing of $\mathcal{C}$ is any subset of edges $S\subseteq\mathcal{C}$ such that 
for all $e$, $e^{\prime}\in S$ satisfy $d_{\mathcal{G}}(e,e^{\prime})\geq r$. The $r$-packing number is defined as
\begin{align}
	N(\mathcal{C},\mathcal{G},r)\triangleq\max \{|S| \ | \ S\subseteq\mathcal{C} , S \text{ is an }r\text{-packing}\}.
\end{align}

\begin{align}
		N(\mathcal{C},\mathcal{G},r)\triangleq\max \{|S| \ | \ S\subseteq\mathcal{C} , S \text{ is an }r\text{-packing}\}.
	\end{align}

