\label{alg:general}
	\caption{General Active Structure Learning Algorithm}
	\textbf{Input:}  The number of nodes $p$, the number of vector samples $n$\\
	\textbf{Output:} Estimated tree structure $\hat{\mathcal{T}}(n)$ \\
	\textbf{Procedure:}
	\begin{algorithmic}[1]\label{algo:generalal}
		\STATE Initialize $i=0$, $T_{0}=0$.
		\WHILE{$T_{i}<np$}
			\STATE $i=i+1$.\\
			\STATE Choose $S_{i}\subseteq [p]$ s.t. $|S_{i}|\geq 1$.\\
			\STATE Obtain $n_{i}$ independent samples $\mathbf{X}_{S_{i}}$ having distribution $P_{S_{i}}$\\
			\STATE Learn partial statistics of the tree model using $\{\mathbf{X}_{S_{1}},\mathbf{X}_{S_{2}},\cdots,\mathbf{X}_{S_{i}}\}$.\\
			\STATE Update $T_{i}=\sum_{j=1}^{i}n_{j}|S_{j}|$.
		\ENDWHILE
		\STATE Return the tree structure $\hat{\mathcal{T}}(n)$ learned from $\{\mathbf{X}_{S_{1}},\mathbf{X}_{S_{2}},\cdots,\mathbf{X}_{S_{i}}\}$.
	\end{algorithmic}

\label{lem:indeppair}
	If $\mathbf{X}=(X_1, X_2, \ldots, X_p) \in \{+1,-1\}^{p}$ is a  binary random vector    drawn from a forest-structured distribution with uniform marginals for each entry $X_{i}$ in $\mathbf{X}$, then the elements  $X_iX_j$
	of the collection of $|\mathcal{E}|$ random variables $\{X_{i}X_{j}~|~\{i,j\}\in\mathcal{E}\}$ are independent.

Since the number of length-$t$ paths in $\mathcal{T}$ is finite, if $\mathcal{T}$ has at least one $\mathcal{P}_{t}$ as its subgraph, Eqn.~\eqref{eq:thopee} can be expressed as
\begin{align}
	K _{t}(\mathcal{T},\rho)=\varliminf_{n\rightarrow \infty}-\frac{1}{n}\log\Pr (E_{t}(\mathcal{P}_{t},n)),
\end{align}
where $\mathcal{P}_{t}$ is a path with length $t$ that is also parameterized by the correlation of adjacent nodes $\rho$. Thus, we only need to consider the path graph. Lemma 1 in \cite{tandon2020exact} shows that for a three-node path $1-2-3$ which is parameterized by $P_{1}(0)=\frac{1}{2}$, $P_{2|1}(0|1)=P_{2|1}(1|0)=\theta$ 
and $P_{3|2}(0|1)=P_{3|2}(1|0)\triangleq\tilde{\theta}_{1}$, we have
\begin{align}
	K_{2}(\mathcal{P}_{2},1-2\theta)=\varliminf_{n\rightarrow \infty}-\frac{1}{n}\log\Pr\big(\hat{\rho}_{13}(n)\geq\hat{\rho}_{12}(n)\big) 
	=-\log\Big(1-\tilde{\theta}_{1}\big(1-\sqrt{4\theta(1-\theta)}\big)\Big),
\end{align}
where $\theta=\frac{1-\rho}{2}$ in the homogeneous Ising trees. To calculate the error exponent of $t$-hop error in the path with $\theta\in (0,0.5)$, we note that
\begin{align}
	K _{t}(\mathcal{P}_{t},1-2\theta)&=\varliminf_{n\rightarrow \infty}-\frac{1}{n}\log\Pr\bigg(\bigcup_{j=1}^{t}\{\hat{\rho}_{k_{1}k_{t+1}}\geq \hat{\rho}_{k_{j}k_{j+1}}\}\bigg)\\*
	&=\varliminf_{n\rightarrow \infty}-\frac{1}{n}\log\Pr\big(\hat{\rho}_{k_{1}k_{t+1}}\geq \hat{\rho}_{k_{1}k_{2}}\big),
\end{align}
which results from the symmetry of the underlying homogeneous tree model.

Taking $\tilde{\theta}_{t-1}\triangleq P_{t+1|2}(0|1)=P_{t+1|2}(1|0)$, we have that
\begin{align}
	\varliminf_{n\rightarrow \infty}-\frac{1}{n}\log\Pr\big(\hat{\rho}_{k_{1}k_{t+1}}\geq \hat{\rho}_{k_{1}k_{2}}\big)=-\log\Big(1-\tilde{\theta}_{t-1}\big(1-\sqrt{4\theta(1-\theta)}\big)\Big).
\end{align}
To prove that $\varliminf_{n\rightarrow \infty}-\frac{1}{n}\log \Pr\big(\hat{\rho}_{k_{1}k_{t+1}}\geq \hat{\rho}_{k_{1}k_{2}}\big)$ strictly increases with   $t$, we only need to show that 
