	\mathcal{D}_{2}(n)&\triangleq\bigcap_{t_{3}\geq 3}\big(E_{t_{3}}(\hat{\mathcal{T}}_{{\rm SCL}},\mathcal{T},\hat{\alpha} n)\big)^{\complement}.
\end{align}
We remark that $\mathcal{D}_{1}$ represents the event that $\hat{\mathcal{T}}_{\rm{SCL}}(\hat{\alpha} n)$  does not have a $t_{1}$-hop error that is independent of a $t_{2}$-hop error for $t_{1},t_{2}\geq 2$, and $\mathcal{D}_{2}$ represents  the event that $\hat{\mathcal{T}}_{\rm{SCL}}(\hat{\alpha} n)$ does not have a $t_3$-hop error for any $t_{3}\geq 3$.

In the following, we   prove $K ( \mathcal{C}\cap \mathcal{D})\geq c_{\rho}K _{{\rm passive}}(\rho)$ and $K (\mathcal{D}^{\complement})\geq c_{\rho}K _{{\rm passive}}(\rho)$.

We begin by proving that $K (\mathcal{D}^{\complement})\geq c_{\rho}K _{{\rm passive}}(\rho)$. To prove this inequality, we only need to prove that $K (\mathcal{D}_{i}^{\complement})\geq c_{\rho}K _{{\rm passive}}(\rho)$ for $i=1,2$, because $\Pr(\mathcal{D}^{\complement})=\Pr(\mathcal{D}_{1}^{\complement}\cup \mathcal{D}_{2}^{\complement})\leq \Pr(\mathcal{D}_{1}^{\complement})+\Pr(\mathcal{D}_{2}^{\complement}).$

For $\mathcal{D}_{1}^{\complement}$, Lemmas~\ref{lem:indeppair} and \ref{lem:mono} show that 
\begin{align}
	K (\mathcal{D}_{1}^{\complement})&\geq K _{t_{1}}(\hat{\mathcal{T}}_{\rm{SCL}},\mathcal{T},\rho,0.8)+K _{t_{2}}(\hat{\mathcal{T}}_{\rm{SCL}},\mathcal{T},\rho,0.8)\\
	&\geq 2K _{2}(\hat{\mathcal{T}}_{\rm{SCL}},\mathcal{T},\rho,0.8)
	= 2\times 0.8\times K _{2}(\hat{\mathcal{T}}_{\rm{SCL}},\mathcal{T},\rho)
	=1.6 K _{{\rm passive}}(\rho).
\end{align}
Since $1.6\geq c_{\rho}$, we have $K (D_{1}^{\complement})\geq c_{\rho}K _{{\rm passive}}(\rho)$. 	For $\mathcal{D}_{2}^{\complement}$, Lemma \ref{lem:thoperror} proves the claim.

We now turn our attention to the event $ \mathcal{C}\cap \mathcal{D}$. The event $\mathcal{D}$ implies that $ \hat{\mathcal{T}}_{\rm{SCL}}$ can have only dependent $2$-hop errors. The number
of dependent edges in $ \hat{\mathcal{T}}_{\rm{SCL}}$ is at most $3d-2$, and Lemma \ref{lem:indeppair} shows that the number of independent products $X_{i}X_{j}$, $\{i,j\}\in\mathcal{E}(\hat{\mathcal{T}}_{{\rm SCL}})$ 
is at least $p-1-(3d-2)\geq 82d-1-(3d-2)=79d+1$. Consider,
\begin{align}
	\Pr( \mathcal{C}\cap \mathcal{D})&=\Pr\Bigg(\!\frac{\sum_{e\in\mathcal{E}(\mathcal{G})\cap\mathcal{E}( \hat{\mathcal{T}}_{\rm{SCL}}(\hat{\alpha} n))}\hat{\rho}_{e}(\hat{\alpha} n)\!+\!\sum_{e^{\prime}\in\mathcal{E}( \hat{\mathcal{T}}_{\rm{SCL}}(\hat{\alpha} n))\backslash\mathcal{E}(\mathcal{G})}\!\hat{\rho}_{e^{\prime}}(\hat{\alpha} n)}{p-1}\!>\!\rho\!+\!\frac{2(1\!-\!\rho)}{9},\mathcal{D}\Bigg)\\
	&\leq\Pr\Bigg(\frac{\sum_{e\in\mathcal{E}(\mathcal{G})\cap\mathcal{E}( \hat{\mathcal{T}}_{\rm{SCL}})}\hat{\rho}_{e}+\sum_{e^{\prime}\in\mathcal{E}( \hat{\mathcal{T}}_{\rm{SCL}})\backslash\mathcal{E}(\mathcal{G})}1}{p-1}>\rho+\frac{2(1-\rho)}{9},\mathcal{D}\Bigg)\\
	&\leq\Pr\Bigg(\frac{3d-2+\sum_{e\in\mathcal{E}(\mathcal{G})\cap\mathcal{E}( \hat{\mathcal{T}}_{\rm{SCL}})}\hat{\rho}_{e}}{p-1}>\rho+\frac{2(1-\rho)}{9},\mathcal{D}\Bigg)\label{ieq:ieq2}\\
	&\leq\Pr\Bigg(\frac{3d-2+\sum_{e\in\mathcal{E}(\mathcal{G})\cap\mathcal{E}( \hat{\mathcal{T}}_{\rm{SCL}})}\hat{\rho}_{e}}{p-1}>\rho+\frac{2(1-\rho)}{9}\Bigg)\\
	&\leq\Pr\Bigg(\frac{3d+\sum_{e\in\mathcal{E}(\mathcal{G})\cap\mathcal{E}( \hat{\mathcal{T}}_{\rm{SCL}})\backslash \{e_{1},e_{2}\}}\hat{\rho}_{e}}{p-1}>\rho+\frac{2(1-\rho)}{9}\Bigg)\label{ieq:ieq3}\\
	&=\Pr\Bigg(\frac{\sum_{e\in\mathcal{E}(\mathcal{G})\cap\mathcal{E}( \hat{\mathcal{T}}_{\rm{SCL}})\backslash \{e_{1},e_{2}\}}\hat{\rho}_{e}}{p-3d-1}>\frac{(p-1)\big[\rho+\frac{2(1-\rho)}{9}\big]-3d}{p-3d-1}\Bigg)\\
	&=\Pr\Bigg(\frac{\sum_{e\in\mathcal{E}(\mathcal{G})\cap\mathcal{E}( \hat{\mathcal{T}}_{\rm{SCL}})\backslash \{e_{1},e_{2}\}}\hat{\rho}_{e}}{p-3d-1}>\rho+\frac{2p-27d-2}{9(p-3d-1)}(1-\rho)\Bigg)\\
	&\leq\Pr\Bigg(\frac{\sum_{e\in\mathcal{E}(\mathcal{G})\cap\mathcal{E}( \hat{\mathcal{T}}_{\rm{SCL}})\backslash \{e_{1},e_{2}\}}\hat{\rho}_{e}}{p-3d-1}>\rho+\frac{1-\rho}{6}\Bigg)\label{ieq:ieq5}\\
