\begin{align}
	N(\mathcal{E}(\mathcal{T}_{i}),\mathcal{T}_{i},2)\geq \frac{|\mathcal{V}(\mathcal{T}_{i})|-1}{2d-1}.
\end{align}
If $|\mathcal{V}(\mathcal{T}_{i})|\geq 2d$, we have $N(\mathcal{E}(\mathcal{T}_{i}),\mathcal{T}_{i},2)\geq\frac{|\mathcal{V}(\mathcal{T}_{i})|-1}{2d-1}\geq\frac{|\mathcal{V}(\mathcal{T}_{i})|}{2d}$. If $|\mathcal{V}(\mathcal{T}_{i})|< 2d$, since $N(\mathcal{E}(\mathcal{T}_{i}),\mathcal{T}_{i},2)\geq 1$, so $N(\mathcal{E}(\mathcal{T}_{i}),\mathcal{T}_{i},2)\geq \frac{|\mathcal{V}(\mathcal{T}_{i})|}{2d}$. Hence, we have  $N(\mathcal{E}(\mathcal{T}_{i}),\mathcal{T}_{i},2)\geq \frac{|\mathcal{V}(\mathcal{T}_{i})|}{2d}$.


Finally, we have
\begin{align}\label{ieq:tilp}
	N(\mathscr{C}_{\mathrm{E}}(\hat{\alpha} n)^{\complement},\mathcal{T}(\mathscr{C}_{\mathrm{V}}(\hat{\alpha} n)^{\complement}),2)&=\sum_{i} N(\mathcal{E}(\mathcal{T}_{i}),\mathcal{T}_{i},2)\geq \frac{\sum_{i}|\mathcal{V}(\mathcal{T}_{i})|}{2d}=\frac{\tilde{p}(\hat{\alpha} n)}{2d}.
\end{align}
If $\tilde{p}(\hat{\alpha} n)\geq 26d$, the inequality in \eqref{ieq:tilp} implies that $N(\mathscr{C}_{\mathrm{E}}(\hat{\alpha} n)^{\complement},\mathcal{T}(\mathscr{C}_{\mathrm{V}}(\hat{\alpha} n)^{\complement}),2)\geq 13$.

